CE => false, self::MOCK_METHOD_NAME => 'getAppliedRates', self::MOCK_VALUE => [ [ 'id' => 0, 'percent' => 1.4, 'rates' => [ [ 'code' => 'sku_1', 'title' => 'title1', 'percent' => 1.1, ], ], ], ] ], ]; if ($isTaxIncluded) { $mockValues[] = [ self::ONCE => false, self::MOCK_METHOD_NAME => 'getStoreRate', self::MOCK_VALUE => self::STORE_RATE ]; } $this->mockReturnValues( $this->mockCalculationTool, $mockValues ); $this->mockCalculationTool->expects($this->atLeastOnce()) ->method('round') ->willReturnCallback( function ($price) { return round($price, 2); } ); } protected function initMockAppliedTaxDataObjectFactory() { $this->mockReturnValues( $this->appliedTaxDataObjectFactory, [ [ self::ONCE => false, self::MOCK_METHOD_NAME => 'create', self::MOCK_VALUE => $this->mockAppliedTax, ] ] ); } private function mockReturnValues($mockObject, $mockMap) { foreach ($mockMap as $valueMap) { if (isset($valueMap[self::WITH_ARGUMENT])) { $mockObject->expects( $valueMap[self::ONCE] == true ? $this->once() : $this->atLeastOnce() )->method($valueMap[self::MOCK_METHOD_NAME])->with($valueMap[self::WITH_ARGUMENT]) ->will( $this->returnValue($valueMap[self::MOCK_VALUE]) ); } else { $mockObject->expects( $valueMap[self::ONCE] == true ? $this->once() : $this->atLeastOnce() )->method($valueMap[self::MOCK_METHOD_NAME])->withAnyParameters() ->will( $this->returnValue($valueMap[self::MOCK_VALUE]) ); } } } } 